    "\u{1FAC0}": "\uC2EC\uC7A5 \uB9E5\uBC15 \uBE68\uAC04 \uC2EC\uC7A5\uD559 \uC7A5\uAE30 \uC9C4\uC9DC \uC2EC\uC7A5 \uD574\uBD80\uD559",
    "\u{1FAC1}": "\uD3D0 \uB0B4\uC26C\uAE30 \uB4E4\uC774\uB9C8\uC2DC\uAE30 \uC228 \uC7A5\uAE30 \uD638\uD761",
    "\u{1F9B7}": "\uC774\uBE68 \uC9C4\uC8FC\uAC19\uC740 \uCE58\uACFC \uCE58\uACFC\uC758\uC0AC \uCE58\uC544 \uD558\uC580 \uD654\uC774\uD2B8",
    "\u{1F9B4}": "\uBF08\uB2E4\uADC0 \uAC1C \uBF08 \uC2A4\uCF08\uB808\uD1A4 \uC704\uC2DC\uBCF8",
    "\u{1F440}": "\uC655\uB208\uC774 \uB208\uC54C \uAD6C\uACBD \uAD6C\uAE00\uB9AC \uB208 \uB9D9\uC18C\uC0AC \uBAB8 \uBCF4\uAE30 \uC2E0\uCCB4 \uC5BC\uAD74 \uC624\uB9C8\uC774\uAC13 \uD6D4\uCCD0\uBD04",
    "\u{1F441}\uFE0F": "\uB208 \uB208 \uD558\uB098 \uB208 \uD55C\uAC1C \uBAB8 \uC2DC\uB825 \uC2E0\uCCB4 \uC5BC\uAD74 \uD55C \uB208",
    "\u{1F445}": "\uD600 \uBA54\uB871 \uBAB8 \uC2E0\uCCB4 \uD565\uB2E4",
    "\u{1F444}": "\uC785 \uB9BD\uC2A4\uD2F1 \uBAB8 \uC2E0\uCCB4 \uC785\uC220 \uD0A4\uC2A4",
    "\u{1FAE6}": "\uC785\uC220\uC744 \uAE68\uBB3C\uACE0 \uC788\uB294 \uC785 \uAC71\uC815 \uAC71\uC815\uC2A4\uB7EC\uC6B4 \uAC81 \uAE68\uBB34\uB294 \uB9BD\uC2A4\uD2F1 \uBC14\uB78C\uD53C\uB294 \uBD88\uC548 \uBF40\uBF40 \uC139\uC2DC \uC608\uBBFC\uD55C \uC608\uBBFC\uD568 \uCD08\uC870\uD568 \uD0A4\uC2A4 \uD50C\uB7EC\uD305",
    "\u{1F476}": "\uC544\uAE30 \uAC13\uB09C\uC544\uAE30 \uC5B4\uB9B0 \uC5B4\uB9B0\uC774 \uC720\uC544 \uC751\uC560\uC751\uC560 \uC784\uC2E0",
    "\u{1F476}\u{1F3FB}": "\uC544\uAE30: \uD558\uC580 \uD53C\uBD80 \uAC13\uB09C\uC544\uAE30 \uC544\uAE30 \uC5B4\uB9B0 \uC5B4\uB9B0\uC774 \uC720\uC544 \uC751\uC560\uC751\uC560 \uC784\uC2E0 \uD558\uC580 \uD53C\uBD80",
    "\u{1F476}\u{1F3FC}": "\uC544\uAE30: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uAC13\uB09C\uC544\uAE30 \uC544\uAE30 \uC5B4\uB9B0 \uC5B4\uB9B0\uC774 \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uC720\uC544 \uC751\uC560\uC751\uC560 \uC784\uC2E0",
    "\u{1F476}\u{1F3FD}": "\uC544\uAE30: \uAC08\uC0C9 \uD53C\uBD80 \uAC08\uC0C9 \uD53C\uBD80 \uAC13\uB09C\uC544\uAE30 \uC544\uAE30 \uC5B4\uB9B0 \uC5B4\uB9B0\uC774 \uC720\uC544 \uC751\uC560\uC751\uC560 \uC784\uC2E0",
    "\u{1F476}\u{1F3FE}": "\uC544\uAE30: \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uAC13\uB09C\uC544\uAE30 \uC544\uAE30 \uC5B4\uB9B0 \uC5B4\uB9B0\uC774 \uC720\uC544 \uC751\uC560\uC751\uC560 \uC784\uC2E0 \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80",
    "\u{1F476}\u{1F3FF}": "\uC544\uAE30: \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAC13\uB09C\uC544\uAE30 \uAC80\uC740\uC0C9 \uD53C\uBD80 \uC544\uAE30 \uC5B4\uB9B0 \uC5B4\uB9B0\uC774 \uC720\uC544 \uC751\uC560\uC751\uC560 \uC784\uC2E0",
    "\u{1F9D2}": "\uC5B4\uB9B0\uC774 \uC131\uC911\uB9BD\uC801\uC778 \uC544\uC774 \uC5B4\uB9B0",
    "\u{1F9D2}\u{1F3FB}": "\uC5B4\uB9B0\uC774: \uD558\uC580 \uD53C\uBD80 \uC131\uC911\uB9BD\uC801\uC778 \uC544\uC774 \uC5B4\uB9B0 \uC5B4\uB9B0\uC774 \uD558\uC580 \uD53C\uBD80",
    "\u{1F9D2}\u{1F3FC}": "\uC5B4\uB9B0\uC774: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uC131\uC911\uB9BD\uC801\uC778 \uC544\uC774 \uC5B4\uB9B0 \uC5B4\uB9B0\uC774 \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80",
    "\u{1F9D2}\u{1F3FD}": "\uC5B4\uB9B0\uC774: \uAC08\uC0C9 \uD53C\uBD80 \uAC08\uC0C9 \uD53C\uBD80 \uC131\uC911\uB9BD\uC801\uC778 \uC544\uC774 \uC5B4\uB9B0 \uC5B4\uB9B0\uC774",
    "\u{1F9D2}\u{1F3FE}": "\uC5B4\uB9B0\uC774: \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uC131\uC911\uB9BD\uC801\uC778 \uC544\uC774 \uC5B4\uB9B0 \uC5B4\uB9B0\uC774 \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80",
    "\u{1F9D2}\u{1F3FF}": "\uC5B4\uB9B0\uC774: \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAC80\uC740\uC0C9 \uD53C\uBD80 \uC131\uC911\uB9BD\uC801\uC778 \uC544\uC774 \uC5B4\uB9B0 \uC5B4\uB9B0\uC774",
    "\u{1F466}": "\uB0A8\uC790 \uC544\uC774 \uC18C\uB144 \uC5B4\uB9B0\uC774 \uC80A\uC740",
    "\u{1F466}\u{1F3FB}": "\uB0A8\uC790 \uC544\uC774: \uD558\uC580 \uD53C\uBD80 \uB0A8\uC790 \uC544\uC774 \uC18C\uB144 \uC5B4\uB9B0\uC774 \uC80A\uC740 \uD558\uC580 \uD53C\uBD80",
    "\u{1F466}\u{1F3FC}": "\uB0A8\uC790 \uC544\uC774: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uB0A8\uC790 \uC544\uC774 \uC18C\uB144 \uC5B4\uB9B0\uC774 \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uC80A\uC740",
    "\u{1F466}\u{1F3FD}": "\uB0A8\uC790 \uC544\uC774: \uAC08\uC0C9 \uD53C\uBD80 \uAC08\uC0C9 \uD53C\uBD80 \uB0A8\uC790 \uC544\uC774 \uC18C\uB144 \uC5B4\uB9B0\uC774 \uC80A\uC740",
    "\u{1F466}\u{1F3FE}": "\uB0A8\uC790 \uC544\uC774: \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uB0A8\uC790 \uC544\uC774 \uC18C\uB144 \uC5B4\uB9B0\uC774 \uC80A\uC740 \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80",
    "\u{1F466}\u{1F3FF}": "\uB0A8\uC790 \uC544\uC774: \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAC80\uC740\uC0C9 \uD53C\uBD80 \uB0A8\uC790 \uC544\uC774 \uC18C\uB144 \uC5B4\uB9B0\uC774 \uC80A\uC740",
