    "\u{1F467}\u{1F3FB}": "\uC5EC\uC790 \uC544\uC774: \uD558\uC580 \uD53C\uBD80 \uB208\uC744 \uBC18\uC9DD\uC774\uB294 \uB538 \uC18C\uB140 \uC219\uB140 \uC5EC\uC790 \uC544\uC774 \uC80A\uC74C \uD558\uC580 \uD53C\uBD80",
    "\u{1F467}\u{1F3FC}": "\uC5EC\uC790 \uC544\uC774: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uB208\uC744 \uBC18\uC9DD\uC774\uB294 \uB538 \uC18C\uB140 \uC219\uB140 \uC5EC\uC790 \uC544\uC774 \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uC80A\uC74C",
    "\u{1F467}\u{1F3FD}": "\uC5EC\uC790 \uC544\uC774: \uAC08\uC0C9 \uD53C\uBD80 \uAC08\uC0C9 \uD53C\uBD80 \uB208\uC744 \uBC18\uC9DD\uC774\uB294 \uB538 \uC18C\uB140 \uC219\uB140 \uC5EC\uC790 \uC544\uC774 \uC80A\uC74C",
