    "\u{1F9CF}": "\uCCAD\uAC01 \uC7A5\uC560\uAC00 \uC788\uB294 \uC0AC\uB78C \uADC0 \uC811\uADFC\uC131 \uCCAD\uAC01\uC7A5\uC560 \uCCAD\uAC01\uC7A5\uC560\uC778 \uCCAD\uB825",
