    "\u{1F977}\u{1F3FF}": "\uB2CC\uC790: \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAD70\uC778 \uAE30\uC220 \uB2CC\uC790 \uBAB0\uB798 \uD558\uAE30 \uBE44\uBC00 \uC0AC\uB78C \uC228\uC740 \uC2F8\uC6C0 \uC554\uC0B4\uC790 \uC57C\uBE44\uD568 \uC804\uC7C1 \uC804\uD22C\uC6D0",
    "\u{1F477}": "\uAC74\uC124 \uB178\uB3D9\uC790 \uAC74\uC124 \uB0A8\uC790 \uB178\uB3D9 \uB178\uB3D9\uC790 \uB9AC\uBAA8\uB378\uB9C1 \uBAA8\uC790 \uBCF4\uC218 \uC0AC\uB78C \uC218\uB9AC \uC548\uC804\uBAA8 \uC7AC\uAC74\uCD95 \uD5EC\uBA67",
    "\u{1F477}\u{1F3FB}": "\uAC74\uC124 \uB178\uB3D9\uC790: \uD558\uC580 \uD53C\uBD80 \uAC74\uC124 \uB0A8\uC790 \uB178\uB3D9 \uB178\uB3D9\uC790 \uB9AC\uBAA8\uB378\uB9C1 \uBAA8\uC790 \uBCF4\uC218 \uC0AC\uB78C \uC218\uB9AC \uC548\uC804\uBAA8 \uC7AC\uAC74\uCD95 \uD558\uC580 \uD53C\uBD80 \uD5EC\uBA67",
    "\u{1F477}\u{1F3FC}": "\uAC74\uC124 \uB178\uB3D9\uC790: \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uAC74\uC124 \uB0A8\uC790 \uB178\uB3D9 \uB178\uB3D9\uC790 \uB9AC\uBAA8\uB378\uB9C1 \uBAA8\uC790 \uBCF4\uC218 \uC0AC\uB78C \uC218\uB9AC \uC548\uC804\uBAA8 \uC5F0\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uC7AC\uAC74\uCD95 \uD5EC\uBA67",
    "\u{1F477}\u{1F3FD}": "\uAC74\uC124 \uB178\uB3D9\uC790: \uAC08\uC0C9 \uD53C\uBD80 \uAC08\uC0C9 \uD53C\uBD80 \uAC74\uC124 \uB0A8\uC790 \uB178\uB3D9 \uB178\uB3D9\uC790 \uB9AC\uBAA8\uB378\uB9C1 \uBAA8\uC790 \uBCF4\uC218 \uC0AC\uB78C \uC218\uB9AC \uC548\uC804\uBAA8 \uC7AC\uAC74\uCD95 \uD5EC\uBA67",
    "\u{1F477}\u{1F3FE}": "\uAC74\uC124 \uB178\uB3D9\uC790: \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uAC74\uC124 \uB0A8\uC790 \uB178\uB3D9 \uB178\uB3D9\uC790 \uB9AC\uBAA8\uB378\uB9C1 \uBAA8\uC790 \uBCF4\uC218 \uC0AC\uB78C \uC218\uB9AC \uC548\uC804\uBAA8 \uC7AC\uAC74\uCD95 \uC9C4\uD55C \uAC08\uC0C9 \uD53C\uBD80 \uD5EC\uBA67",
    "\u{1F477}\u{1F3FF}": "\uAC74\uC124 \uB178\uB3D9\uC790: \uAC80\uC740\uC0C9 \uD53C\uBD80 \uAC74\uC124 \uAC80\uC740\uC0C9 \uD53C\uBD80 \uB0A8\uC790 \uB178\uB3D9 \uB178\uB3D9\uC790 \uB9AC\uBAA8\uB378\uB9C1 \uBAA8\uC790 \uBCF4\uC218 \uC0AC\uB78C \uC218\uB9AC \uC548\uC804\uBAA8 \uC7AC\uAC74\uCD95 \uD5EC\uBA67",
