    "\u{1F9DE}": "\uC9C0\uB2C8 \uB7A8\uD504 \uBB38\uC9C0\uB974\uAE30 \uC18C\uC6D0 \uC815\uB839 \uD310\uD0C0\uC9C0",
    "\u{1F9DE}\u200D\u2642\uFE0F": "\uB0A8\uC790 \uC9C0\uB2C8 \uB7A8\uD504 \uBB38\uC9C0\uB974\uAE30 \uC18C\uC6D0 \uC815\uB839 \uC9C0\uB2C8 \uD310\uD0C0\uC9C0",
    "\u{1F9DE}\u200D\u2640\uFE0F": "\uC5EC\uC790 \uC9C0\uB2C8 \uB7A8\uD504 \uBB38\uC9C0\uB974\uAE30 \uC18C\uC6D0 \uC815\uB839 \uC9C0\uB2C8 \uD310\uD0C0\uC9C0",
    "\u{1F9DF}": "\uC880\uBE44 \uACF5\uD3EC \uC544\uD3EC\uCE7C\uB9BD\uC2A4 \uC5B8\uB370\uB4DC \uC6CC\uD0B9 \uB370\uB4DC \uD560\uB85C\uC708 \uD638\uB7EC",
