    "\u{1F9CC}": "\uD2B8\uB864 \uAD34\uBB3C \uB3D9\uD654 \uBAAC\uC2A4\uD130 \uD2B8\uB864\uB9C1 \uD310\uD0C0\uC9C0",
    "\u{1FAC8}": "\uD138\uBCF5\uC22D\uC774 \uAC70\uC778 \uAD34\uC0DD\uBA85\uCCB4 \uBE45\uD48B \uC0AC\uC2A4\uCF70\uCE58 \uC124\uC778 \uC232 \uD138",
    "\u{1F486}": "\uB9C8\uC0AC\uC9C0 \uBC1B\uB294 \uC0AC\uB78C \uACBD\uB77D \uACE8\uCE58\uC544\uD514 \uAE34\uC7A5 \uB450\uD1B5 \uB9C8\uC0AC\uC9C0 \uB9C8\uC0AC\uC9C0\uB97C \uBC1B\uB294 \uC0AC\uB78C \uB9E4\uB048 \uC0B4\uB871 \uC2A4\uD30C \uC5BC\uAD74 \uC694\uBC95 \uC774\uC644 \uCE58\uB8CC \uD14C\uB77C\uD53C \uD2B8\uB9AC\uD2B8\uBA3C\uD2B8",
