    "\u{1F6E5}\uFE0F": "\uBAA8\uD130\uBCF4\uD2B8 \uBCF4\uD2B8",
    "\u{1F6A2}": "\uC120\uBC15 \uBC14\uB2E4 \uBC30 \uC2B9\uAC1D \uC5EC\uD589 \uD0C0\uC774\uD0C0\uB2C9",
    "\u2708\uFE0F": "\uBE44\uD589\uAE30 \uBE44\uD589 \uC5EC\uD589 \uC81C\uD2B8 \uD56D\uACF5",
    "\u{1F6E9}\uFE0F": "\uACBD\uBE44\uD589\uAE30 \uBE44\uD589\uAE30 \uC18C\uD615\uBE44\uD589\uAE30 \uD56D\uACF5\uAE30",
    "\u{1F6EB}": "\uBE44\uD589\uAE30 \uC774\uB959 \uBE44\uD589\uAE30 \uC774\uB959 \uCCB4\uD06C\uC778 \uCD9C\uBC1C",
    "\u{1F6EC}": "\uBE44\uD589\uAE30 \uCC29\uB959 \uB3C4\uCC29 \uB3C4\uCC29\uD558\uB294 \uC911 \uB79C\uB529 \uC911 \uBE44\uD589\uAE30 \uD56D\uACF5\uAE30",
    "\u{1FA82}": "\uB099\uD558\uC0B0 \uC2A4\uCE74\uC774\uB2E4\uC774\uBE59 \uD328\uB7EC\uC138\uC77C\uB9C1 \uD589\uAE00\uB77C\uC774\uB354",
    "\u{1F4BA}": "\uC88C\uC11D \uC758\uC790 \uC790\uB9AC",
    "\u{1F681}": "\uD5EC\uB9AC\uCF65\uD130 \uAD50\uD1B5\uC218\uB2E8 \uB85C\uD50C\uCF65\uD130 \uC5EC\uD589 \uCF65\uD130 \uD5EC\uAE30",
    "\u{1F69F}": "\uB9E4\uB2EC\uB9B0 \uCF00\uC774\uBE14\uCE74 \uC790\uAE30\uBD80\uC0C1 \uC790\uAE30\uBD80\uC0C1 \uC5F4\uCC28 \uCCA0\uB3C4 \uCF00\uC774\uBE14\uCE74",
    "\u{1F6A0}": "\uC0B0\uC545 \uCF00\uC774\uBE14\uCE74 \uACE4\uB3CC\uB77C \uAD50\uD1B5\uC218\uB2E8 \uC0B0 \uC2A4\uD0A4 \uB9AC\uD504\uD2B8 \uCF00\uC774\uBE14 \uCF00\uC774\uBE14\uCE74",
    "\u{1F6A1}": "\uCF00\uC774\uBE14\uCE74 \uACE4\uB3CC\uB77C \uACF5\uC911 \uC0B0\uC545 \uCF00\uC774\uBE14\uCE74 \uCC28",
    "\u{1F6F0}\uFE0F": "\uC778\uACF5\uC704\uC131 \uC6B0\uC8FC",
