    "\u{1F6F8}": "\uBE44\uD589\uC811\uC2DC UFO \uC678\uACC4\uC778 \uC6B0\uC8FC \uC0DD\uBA85\uCCB4",
    "\u{1F6CE}\uFE0F": "\uD638\uCD9C \uBCA8 \uB370\uC2A4\uD06C\uBCA8 \uBCA8 \uD638\uD154",
