    "\u231A": "\uC2DC\uACC4 \uC190\uBAA9 \uC2DC\uACC4 \uC2DC\uAC04",
    "\u23F0": "\uC54C\uB78C \uC2DC\uACC4 \uB2A6\uC740 \uB300\uAE30 \uC2DC\uAC04 \uC2DC\uACC4 \uC54C\uB78C",
