    "\u{1F55B}": "\uC5F4\uB450 \uC2DC 12 12:00 12\uC2DC \uC2DC\uACC4 \uC815\uAC01",
    "\u{1F567}": "\uC5F4\uB450 \uC2DC \uBC18 12:30 12\uC2DC 30\uBD84 30\uBD84 \uC2DC\uAC04 \uC2DC\uACC4 \uC5F4\uB450 \uC2DC",
