    "\u{1F554}": "\uB2E4\uC12F \uC2DC 00\uBD84 5 5:00 5\uC2DC \uC2DC\uAC04 \uC2DC\uACC4 \uC815\uAC01",
    "\u{1F560}": "\uB2E4\uC12F \uC2DC \uBC18 30\uBD84 5:30 5\uC2DC 30\uBD84 \uC2DC\uAC04 \uC2DC\uACC4",
    "\u{1F555}": "\uC5EC\uC12F \uC2DC 00\uBD84 6 6:00 6\uC2DC \uC2DC\uAC04 \uC2DC\uACC4 \uC815\uAC01",
    "\u{1F561}": "\uC5EC\uC12F \uC2DC \uBC18 30\uBD84 6:30 6\uC2DC 30\uBD84 \uC2DC\uAC04 \uC2DC\uACC4",
