    "\u264E": "\uCC9C\uCE6D\uC790\uB9AC \uBCC4 \uBCC4\uC790\uB9AC \uBCC4\uC810 \uC800\uC6B8 \uC815\uC758 \uCC9C\uCE6D",
    "\u264F": "\uC804\uAC08\uC790\uB9AC \uBCC4 \uBCC4\uC790\uB9AC \uBCC4\uC810 \uC2A4\uCF5C\uD53C\uC628 \uC804\uAC08",
    "\u2650": "\uC0AC\uC218\uC790\uB9AC \uAD81\uC218 \uBCC4 \uBCC4\uC790\uB9AC \uC0AC\uC218 \uD65C",
