    "\u{1F501}": "\uC804\uACE1 \uBC18\uBCF5 \uC7AC\uC0DD \uAF2C\uB9AC\uB97C \uBB34\uB294 \uD654\uC0B4\uD45C \uBC18\uBCF5 \uBC18\uBCF5 \uBC84\uD2BC \uC2DC\uACC4\uBC29\uD5A5 \uD654\uC0B4\uD45C",
    "\u{1F502}": "\uD55C \uACE1 \uBC18\uBCF5 \uC7AC\uC0DD \uAF2C\uB9AC\uB97C \uBB34\uB294 \uD654\uC0B4\uD45C\uC640 \uC22B\uC790 1 \uC2DC\uACC4\uBC29\uD5A5 \uD55C \uACE1 \uBC18\uBCF5 \uC7AC\uC0DD \uBC84\uD2BC \uD55C\uBC88 \uD654\uC0B4\uD45C",
    "\u25B6\uFE0F": "\uC7AC\uC0DD \uBC84\uD2BC \uC0BC\uAC01\uD615 \uC624\uB978\uCABD \uC7AC\uC0DD \uD50C\uB808\uC774 \uD654\uC0B4\uD45C",
    "\u23E9": "\uBE68\uB9AC \uAC10\uAE30 \uBC84\uD2BC \uB450 \uAC1C \uBE68\uB9AC \uAC10\uAE30 \uC55E\uC73C\uB85C \uC624\uB978\uCABD \uD654\uC0B4\uD45C \uB450 \uAC1C \uD654\uC0B4\uD45C",
    "\u23ED\uFE0F": "\uB2E4\uC74C \uD2B8\uB799 \uBC84\uD2BC \uB2E4\uC74C \uC7A5\uBA74 \uB2E4\uC74C \uD2B8\uB799 \uC0BC\uAC01\uD615 \uD654\uC0B4\uD45C",
    "\u23EF\uFE0F": "\uC7AC\uC0DD \uB610\uB294 \uC77C\uC2DC \uC815\uC9C0 \uBC84\uD2BC \uC0BC\uAC01\uD615 \uC624\uB978\uCABD \uC77C\uC2DC \uC815\uC9C0 \uC7AC\uC0DD \uD654\uC0B4\uD45C",
    "\u25C0\uFE0F": "\uBC18\uB300\uB85C \uBC84\uD2BC \uB418\uB3CC\uB9AC\uAE30 \uBC84\uD2BC \uBC18\uB300 \uBCF5\uADC0 \uC0BC\uAC01\uD615 \uD654\uC0B4\uD45C",
    "\u23EA": "\uB418\uAC10\uAE30 \uBC84\uD2BC \uB418\uAC10\uAE30 \uB450 \uAC1C \uBE68\uB9AC \uB418\uAC10\uAE30 \uBC84\uD2BC \uC67C\uCABD \uD654\uC0B4\uD45C \uB450 \uAC1C \uD654\uC0B4\uD45C",
