    "\u{1F53C}": "\uC62C\uB9AC\uAE30 \uBC84\uD2BC \uC0BC\uAC01\uD615 \uC704\uCABD \uC0BC\uAC01\uD615 \uC704\uCABD \uC0BC\uAC01\uD615 \uBC84\uD2BC",
    "\u23EB": "\uBE68\uB9AC \uC62C\uB9AC\uAE30 \uBC84\uD2BC \uACE0\uC18D\uC0C1\uC2B9 \uBC84\uD2BC \uB354\uBE14 \uC704\uB85C \uC704\uCABD \uD654\uC0B4\uD45C",
    "\u{1F53D}": "\uB0B4\uB9AC\uAE30 \uBC84\uD2BC \uB2E4\uC6B4 \uBC84\uD2BC \uC0BC\uAC01\uD615 \uC544\uB798\uCABD \uC0BC\uAC01\uD615 \uC544\uB798\uCABD \uC0BC\uAC01\uD615 \uBC84\uD2BC",
    "\u23EC": "\uBE68\uB9AC \uB0B4\uB9AC\uAE30 \uBC84\uD2BC \uAE09\uD558\uAC15 \uBC84\uD2BC \uB354\uBE14 \uC544\uB798\uB85C \uC544\uB798\uCABD \uD654\uC0B4\uD45C \uC544\uB7AB\uCABD \uD654\uC0B4\uD45C",
    "\u23F8\uFE0F": "\uC77C\uC2DC \uC815\uC9C0 \uBC84\uD2BC \uB354\uBE14 \uC77C\uC2DC \uC815\uC9C0 \uC815\uC9C0",
