    "\u{1F3A6}": "\uC601\uD654 \uADF9\uC7A5 \uC2DC\uB124\uB9C8 \uC601\uD654\uAD00",
    "\u{1F505}": "\uBC1D\uAE30 \uB0AE\uC74C \uB0AE\uC740 \uBC1D\uAE30 \uBC1D\uAE30 \uBC1D\uAE30 \uC870\uC808 \uBC1D\uAE30 \uC870\uC808 \uBC84\uD2BC \uC5B4\uB450\uC6C0 \uC5B4\uB450\uC6C0 \uD45C\uC2DC",
    "\u{1F506}": "\uBC1D\uAE30 \uB192\uC74C \uB192\uC740 \uBC1D\uAE30 \uBC1D\uAE30 \uBC84\uD2BC \uBC1D\uC740 \uBC1D\uC74C \uBC1D\uC74C \uD45C\uC2DC \uBE5B",
