    "\u{1F4F4}": "\uD734\uB300\uC804\uD654 \uB044\uAE30 \uAEBC\uC9D0 \uBAA8\uBC14\uC77C\uD3F0 \uC140\uD3F0 \uC804\uC6D0\uC774 \uAEBC\uC9C4 \uD734\uB300\uC804\uD654 \uC804\uD654\uAE30 \uD734\uB300\uC804\uD654 \uC804\uC6D0 \uB044\uAE30",
    "\u2640\uFE0F": "\uC5EC\uC131 \uAE30\uD638 \uAE30\uD638 \uC5EC\uC131",
    "\u2642\uFE0F": "\uB0A8\uC131 \uAE30\uD638 \uAE30\uD638 \uB0A8\uC131",
