    "\u2796": "\uBE7C\uAE30 \uB9C8\uC774\uB108\uC2A4 \uBE7C\uAE30 \uD45C\uC2DC \uC218\uD559 \uC9C4\uD55C \uBE7C\uAE30 \uD45C\uC2DC",
    "\u2797": "\uB098\uB204\uAE30 \uB098\uB204\uAE30 \uD45C\uC2DC \uC218\uD559 \uC9C4\uD55C \uB098\uB204\uAE30 \uD45C\uC2DC",
    "\u{1F7F0}": "\uB4F1\uD638 \uAE30\uD638 \uAC19\uC74C \uB2F5 \uB3D9\uB4F1 \uC815\uB2F5 \uD3C9\uB4F1",
    "\u267E\uFE0F": "\uBB34\uD55C \uBAFC\uBE44\uC6B0\uC2A4 \uC601\uC6D0",
