    "\u2049\uFE0F": "\uB290\uB08C\uD45C\uC640 \uBB3C\uC74C\uD45C \uB290\uB08C\uD45C \uBB38\uC7A5 \uBD80\uD638 \uBB3C\uC74C\uD45C \uBD80\uD638 \uC778\uD14C\uB7EC\uBC45 \uC9C8\uBB38",
    "\u2753": "\uBE68\uAC04\uC0C9 \uBB3C\uC74C\uD45C ? \uBB38\uC7A5 \uBD80\uD638 \uBB3C\uC74C \uBB3C\uC74C\uD45C \uC758\uBB38 \uC9C8\uBB38",
    "\u2754": "\uD558\uC580\uC0C9 \uBB3C\uC74C\uD45C \uBB38\uC7A5 \uBD80\uD638 \uBB3C\uC74C \uBB3C\uC74C\uD45C \uC758\uBB38 \uC9C8\uBB38",
    "\u2755": "\uD558\uC580\uC0C9 \uB290\uB08C\uD45C ! \uB290\uB08C \uB290\uB08C\uD45C \uBB38\uC7A5 \uBD80\uD638 \uBD80\uD638 \uD558\uC580\uC0C9 \uBB3C\uC74C\uD45C \uBD80\uD638",
    "\u2757": "\uBE68\uAC04\uC0C9 \uB290\uB08C\uD45C \uB290\uB08C\uD45C \uBB38\uC7A5 \uBD80\uD3EC \uBD80\uD638",
