    "\u269C\uFE0F": "\uBC31\uD569 \uBB38\uC7A5 \uAE30\uC0AC \uBB38\uC7A5 \uBC31\uD569",
    "\u{1F531}": "\uC0BC\uC9C0\uCC3D \uB2FB \uB3C4\uAD6C \uBC30 \uC0C1\uC9D5 \uC5E0\uBE14\uB7FC \uCC3D \uD3EC\uC138\uC774\uB3C8",
    "\u{1F4DB}": "\uC774\uB984\uD45C \uBA85\uCC30 \uBC30\uC9C0 \uC774\uB984",
    "\u{1F530}": "\uC77C\uBCF8 \uCD08\uBCF4\uC6B4\uC804 \uD45C\uC2DC V \uBAA8\uC591 \uADF8\uB9B0 \uB178\uB780\uC0C9 \uB178\uB780\uC0C9 \uCD08\uB85D\uC0C9 \uC774\uD30C\uB9AC \uBAA8\uC591 \uC77C\uBCF8 \uC77C\uBCF8 \uCD08\uBCF4\uC6B4\uC804\uC790 \uC2EC\uBCFC \uC78E \uCD08\uB85D\uC0C9 \uCD08\uBCF4 \uCD08\uBCF4\uC790",
    "\u2B55": "\uBE68\uAC04\uC0C9 \uC815\uB2F5 \uB3D9\uADF8\uB77C\uBBF8 \uB3D9\uADF8\uB77C\uBBF8 \u3147 \uC6D0 \uD06C\uACE0 \uC9C4\uD55C \uB3D9\uADF8\uB77C\uBBF8",
    "\u2705": "\uCCB4\uD06C \uD45C\uC2DC \uBC84\uD2BC \uC644\uB8CC\uB428 \uCCB4\uD06C \uCCB4\uD06C \uD45C\uC2DC \uD2F1 \uD655\uC778\uD568",
    "\u2611\uFE0F": "\uCCB4\uD06C\uBC15\uC2A4 \uC644\uB8CC \uCCB4\uD06C \uCCB4\uD06C\uC0C1\uC790 \uCCB4\uD06C\uC644\uB8CC \uCCB4\uD06C\uD45C\uC2DC\uB41C \uD22C\uD45C\uB780 \uD22C\uD45C \uD22C\uD45C\uC6A9\uC9C0 \uD2F1",
    "\u2714\uFE0F": "\uCCB4\uD06C \uD45C\uC2DC \uC9C4\uD55C \uCCB4\uD06C \uD45C\uC2DC \uC9C4\uD55C \uCCB4\uD06C\uD45C\uC2DC \uCCB4\uD06C \uCCB4\uD06C\uD45C\uC2DC \uD588\uC74C \uD655\uC778\uD568",
    "\u274C": "\uC5D1\uC2A4 \uD45C\uC2DC x \uACF1\uC148 \uACF1\uD558\uAE30 \uC5D1\uC2A4 \uC5D1\uC2A4\uD45C",
    "\u274E": "\uC5D1\uC2A4 \uD45C\uC2DC \uBC84\uD2BC x \uACF1\uC148 \uACF1\uD558\uAE30 \uC0C1\uC790 \uC548 \uC5D1\uC2A4 \uD45C\uC2DC \uC5D1\uC2A4 \uD45C\uC2DC \uCD08\uB85D \uC0C1\uC790 \uC548 \uC5D1\uC2A4 \uD45C\uC2DC",
    "\u27B0": "\uACE0\uB9AC \uACF1\uC2AC \uB3D9\uADF8\uB797\uAC8C \uB9D0\uB9B0 \uACE0\uB9AC \uB8E8\uD504",
