    "\u{1F202}\uFE0F": '\uC77C\uBCF8\uC5B4 "\uBD09\uC0AC\uB8CC" \uBC84\uD2BC "\uBD09\uC0AC\uB8CC" sa \uC0AC \uC77C\uBCF8\uC5B4 \uCE74\uD0C0\uCE74\uB098',
