    "\u{1F236}": '\uC788\uC744 \uC720 "\uBB34\uB8CC \uC544\uB2D8" \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uBB34\uB8CC \uC544\uB2D8" \uBC84\uD2BC \uC788\uC74C \uD45C\uC758\uBB38\uC790',
    "\u{1F22F}": '\uAC00\uB9AC\uD0AC \uC9C0 "\uC608\uC57D" \uAC00\uB9AC\uD0A4\uB2E4 \uC190\uAC00\uB77D \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uC608\uC57D" \uBC84\uD2BC \uC9C0\uCE6D \uD45C\uC758\uBB38\uC790',
    "\u{1F250}": '\uC5BB\uC744 \uB4DD "\uD560\uC778" \uC774\uB4DD \uC774\uC775 \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uD560\uC778" \uBC84\uD2BC \uD45C\uC758\uBB38\uC790 \uD68D\uB4DD',
    "\u{1F239}": '\uB098\uB20C \uD560 "\uD560\uC778" \uB098\uB204\uAE30 \uB098\uB214 \uBD84\uB9AC \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uD560\uC778" \uBC84\uD2BC \uD45C\uC758\uBB38\uC790',
    "\u{1F21A}": '\uC5C6\uC744 \uBB34 "\uBB34\uB8CC" \uC5C6\uC74C \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uBB34\uB8CC" \uBC84\uD2BC \uD45C\uC758 \uBB38\uC790',
    "\u{1F232}": '\uAE08\uD560 \uAE08 "\uAE08\uC9C0" \uAE08\uC9C0 \uAE08\uD558\uB2E4 \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uAE08\uC9C0" \uBC84\uD2BC \uCC28\uB2E8 \uD45C\uC758 \uBB38\uC790',
    "\u{1F251}": '\uC633\uC744 \uAC00 "\uAC00\uB2A5" \uB9DE\uC74C \uC62E\uC74C \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uAC00\uB2A5" \uBC84\uD2BC \uD45C\uC758\uBB38\uC790 \uD5C8\uAC00',
    "\u{1F238}": '\uAC70\uB4ED \uC2E0 "\uC2E0\uCCAD" \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uC2E0\uCCAD" \uBC84\uD2BC \uD45C\uC758\uBB38\uC790',
    "\u{1F234}": '\uD569\uD560 \uD569 \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uD569\uACA9" \uBC84\uD2BC \uC804\uCCB4 \uD45C\uC758 \uBB38\uC790 \uD569 \uD569\uACA9 \uD569\uD558\uAE30',
    "\u{1F233}": '\uBE4C \uACF5 "\uBE44\uC5B4 \uC788\uC74C" \uACF5 \uBE44\uC5B4\uC788\uC74C \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uBE44\uC5B4 \uC788\uC74C" \uBC84\uD2BC \uD145 \uBE48 \uC0C1\uD0DC \uD45C\uC758\uBB38\uC790',
    "\u3297\uFE0F": '\uC6D0 \uC548\uC758 \uCD95\uD558 \uD45C\uC758\uBB38\uC790 "\uCD95\uD558" \uBE4C \uCD95 \uC6D0 \uD45C\uC2DC\uB41C \uCD95\uD558 \uD45C\uC758\uBB38\uC790 \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uCD95\uD558" \uBC84\uD2BC \uC911\uAD6D\uC5B4 \uCD95\uD558 \uD45C\uC758\uBB38\uC790',
    "\u3299\uFE0F": '\uC6D0 \uD45C\uC2DC\uB41C \uBE44\uBC00 \uD45C\uC758\uBB38\uC790 "\uBE44\uBC00" \uBE44\uBC00 \uC228\uAE38 \uBE44 \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uBE44\uBC00" \uBC84\uD2BC \uC911\uAD6D\uC5B4 \uD45C\uC758\uBB38\uC790',
    "\u{1F23A}": '\uBCBC\uC2AC \uAD00 "\uC601\uC5C5 \uC911" \uC601 \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uC601\uC5C5 \uC911" \uBC84\uD2BC \uD45C\uC758\uBB38\uC790',
    "\u{1F235}": '\uCC30 \uB9CC \uAC00\uB4DD \uB9CC \uBE48\uBC29\uC5C6\uC74C \uC77C\uBCF8\uC5B4 \uC77C\uBCF8\uC5B4 "\uBE48\uBC29\uC5C6\uC74C" \uBC84\uD2BC \uD45C\uC758\uBB38\uC790 \u6E80',
    "\u{1F534}": "\uBE68\uAC04 \uC6D0 \uAE30\uD558\uD559 \uBB34\uB2AC \uB808\uB4DC \uC11C\uD074 \uBE68\uAC04\uC0C9 \uBE68\uAC15 \uC6D0 \uD070 \uBE68\uAC04 \uC6D0",
    "\u{1F7E0}": "\uC624\uB80C\uC9C0\uC0C9 \uC6D0 \uB3D9\uADF8\uB77C\uBBF8 \uC624\uB80C\uC9C0\uC0C9 \uC6D0",
