    "\u{1F7EA}": "\uBCF4\uB77C\uC0C9 \uC0AC\uAC01\uD615 \uBCF4\uB77C\uC0C9 \uC0AC\uAC01\uD615",
    "\u{1F7EB}": "\uAC08\uC0C9 \uC0AC\uAC01\uD615 \uAC08\uC0C9 \uC0AC\uAC01\uD615",
    "\u2B1B": "\uD070 \uAC80\uC740\uC0C9 \uC0AC\uAC01\uD615 \uAC80\uC740\uC0C9 \uD070 \uC0AC\uAC01\uD615 \uAE30\uD558\uD559 \uBB34\uB2AC \uBB34\uB2AC \uBE14\uB799 \uB77C\uC9C0 \uC0AC\uAC01\uD615 \uC0AC\uAC01\uD615",
    "\u2B1C": "\uD070 \uD770\uC0C9 \uC0AC\uAC01\uD615 \uAE30\uD558\uD559 \uBB34\uB2AC \uBB34\uB2AC \uC0AC\uAC01\uD615 \uD654\uC774\uD2B8 \uB77C\uC9C0 \uC0AC\uAC01\uD615 \uD770\uC0C9 \uD070 \uC0AC\uAC01\uD615",
    "\u25FC\uFE0F": "\uC911\uAC04 \uAC80\uC740\uC0C9 \uC0AC\uAC01\uD615 \uAC80\uC815\uC0C9 \uC911\uAC04 \uC0AC\uAC01\uD615 \uAE30\uD558\uD559 \uBB34\uB2AC \uBB34\uB2AC \uBE14\uB799 \uBBF8\uB514\uC5C4 \uC0AC\uAC01\uD615 \uC0AC\uAC01\uD615 \uC911\uAC04\uD06C\uAE30 \uAC80\uC740\uC0C9 \uC0AC\uAC01\uD615",
    "\u25FB\uFE0F": "\uC911\uAC04 \uD770\uC0C9 \uC0AC\uAC01\uD615 \uAE30\uD558\uD559 \uBB34\uB2AC \uBB34\uB2AC \uC0AC\uAC01\uD615 \uD654\uC774\uD2B8 \uBBF8\uB514\uC5C4 \uC0AC\uAC01\uD615 \uD770\uC0C9 \uC911\uAC04 \uC0AC\uAC01\uD615",
    "\u25FE": "\uC911\uAC01 \uC791\uC740 \uAC80\uC740\uC0C9 \uC0AC\uAC01\uD615 \uAC80\uC740\uC0C9 \uBBF8\uB514\uC5C4-\uC2A4\uBAB0 \uC0AC\uAC01\uD615 \uAE30\uD558\uD559 \uBB34\uB2AC \uBB34\uB2AC \uBE14\uB799 \uBBF8\uB514\uC5C4-\uC2A4\uBAB0 \uC0AC\uAC01\uD615 \uC0AC\uAC01\uD615",
    "\u25FD": "\uC911\uAC04 \uC791\uC740 \uD770\uC0C9 \uC0AC\uAC01\uD615 \uAE30\uD558\uD559 \uBB34\uB2AC \uBB34\uB2AC \uC0AC\uAC01\uD615 \uD654\uC774\uD2B8 \uBBF8\uB514\uC5C4-\uC2A4\uBAB0 \uC0AC\uAC01\uD615 \uD770\uC0C9 \uBBF8\uB514\uC5C4-\uC2A4\uBAB0 \uC0AC\uAC01\uD615",
    "\u25AA\uFE0F": "\uC791\uC740 \uAC80\uC740\uC0C9 \uC0AC\uAC01\uD615 \uAC80\uC740\uC0C9 \uC791\uC740 \uC0AC\uAC01\uD615 \uAE30\uD558\uD559 \uBB34\uB2AC \uBB34\uB2AC \uBE14\uB799 \uC2A4\uBAB0 \uC0AC\uAC01\uD615 \uC0AC\uAC01\uD615",
    "\u25AB\uFE0F": "\uC791\uC740 \uD770\uC0C9 \uC0AC\uAC01\uD615 \uAE30\uD558\uD559 \uBB34\uB2AC \uBB34\uB2AC \uC0AC\uAC01\uD615 \uD654\uC774\uD2B8 \uC2A4\uBAB0 \uC0AC\uAC01\uD615",
    "\u{1F536}": "\uD070 \uC8FC\uD669\uC0C9 \uB9C8\uB984\uBAA8 \uB77C\uC9C0 \uC624\uB80C\uC9C0 \uB9C8\uB984\uBAA8 \uB9C8\uB984\uBAA8 \uC624\uB80C\uC9C0\uC0C9 \uC8FC\uD669\uC0C9",
    "\u{1F537}": "\uD070 \uD30C\uB780\uC0C9 \uB9C8\uB984\uBAA8 \uAE30\uD558\uD559 \uBB34\uB2AC \uB77C\uC9C0 \uBE14\uB8E8 \uB9C8\uB984\uBAA8 \uB9C8\uB984\uBAA8 \uD30C\uB780\uC0C9 \uD30C\uB791",
    "\u{1F538}": "\uC791\uC740 \uC8FC\uD669\uC0C9 \uB9C8\uB984\uBAA8 \uAE30\uD558\uD559 \uBB34\uB2AC \uB9C8\uB984\uBAA8 \uC624\uB80C\uC9C0\uC0C9 \uC8FC\uD669\uC0C9",
    "\u{1F539}": "\uC791\uC740 \uD30C\uB780\uC0C9 \uB9C8\uB984\uBAA8 \uAE30\uD558\uD559 \uBB34\uB2AC \uB9C8\uB984\uBAA8 \uC2A4\uBAB0 \uBE14\uB8E8 \uB9C8\uB984\uBAA8 \uD30C\uB780\uC0C9 \uD30C\uB791",
